// lib/views/splash_screen.dartimport 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../../../view_models/user/login_view_model.dart';// 🔥 Định nghĩa màu chủ đạo (Tím)const Color kPrimaryColor = Color(0xFF6C63FF);class SplashScreen extends StatefulWidget {  const SplashScreen({Key? key}) : super(key: key);  @override  State<SplashScreen> createState() => _SplashScreenState();}class _SplashScreenState extends State<SplashScreen> {  @override  void initState() {    super.initState();    WidgetsBinding.instance.addPostFrameCallback((_) {      _checkLoginAndNavigate();    });  }  Future<void> _checkLoginAndNavigate() async {    // Độ trễ để thấy branding    await Future.delayed(const Duration(seconds: 2));    if (!mounted) return;    await context.read<LoginViewModel>().autoLogin(context);    if (!mounted) return;    Navigator.pushReplacementNamed(context, '/home');  }  @override  Widget build(BuildContext context) {    return Scaffold(      backgroundColor: Colors.white,      body: Center(        child: Column(          mainAxisAlignment: MainAxisAlignment.center,          children: [            // Logo App với hiệu ứng nền nhẹ            Container(              width: 160,              height: 160,              padding: const EdgeInsets.all(20),              decoration: BoxDecoration(                // 🔥 UPDATED: Màu nền Tím nhạt                color: kPrimaryColor.withOpacity(0.1),                shape: BoxShape.circle,              ),              child: Image.asset(                'assets/icon/job_seeker.png',                fit: BoxFit.contain,                // 🔥 UPDATED: Icon fallback màu Tím                errorBuilder: (context, error, stackTrace) =>                const Icon(Icons.work_rounded, size: 80, color: kPrimaryColor),              ),            ),            const SizedBox(height: 40),            // Loading indicator màu chủ đạo            const CircularProgressIndicator(              // 🔥 UPDATED: Loading màu Tím              valueColor: AlwaysStoppedAnimation<Color>(kPrimaryColor),              strokeWidth: 3,            ),            const SizedBox(height: 24),            // Tên App            const Text(              "Job Seeker",              style: TextStyle(                fontSize: 32,                fontWeight: FontWeight.bold,                // 🔥 UPDATED: Text màu Tím                color: kPrimaryColor,                letterSpacing: 1.5,              ),            ),            const SizedBox(height: 8),            // Slogan            Text(              "Kết nối tìm việc làm",              style: TextStyle(                fontSize: 16,                fontWeight: FontWeight.w500,                color: Colors.grey[500],              ),            ),          ],        ),      ),    );  }}